import{_ as a,o as e,c as i,ag as d}from"./chunks/framework.C9sp7nFj.js";const p=JSON.parse('{"title":"WaitConvDis 等待传送带增量","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/14. 传送带跟随指令/WaitConvDis.md","filePath":"3. 指令/14. 传送带跟随指令/WaitConvDis.md","lastUpdated":1778862643000}'),o={name:"3. 指令/14. 传送带跟随指令/WaitConvDis.md"};function r(n,t,s,h,l,c){return e(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="waitconvdis-等待传送带增量" tabindex="-1">WaitConvDis 等待传送带增量 <a class="header-anchor" href="#waitconvdis-等待传送带增量" aria-label="Permalink to &quot;WaitConvDis 等待传送带增量&quot;">​</a></h1><p>该指令用于使机器人沿传送带正方向与传送带同步运动到一定增量后再执行后续的指令，从而让机器人能够达到延时指定增量再运动的需求。与 Wait 指令不同的是，本指令是需要等固定增量而 Wait 是需要等固定时间。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>WaitConvDis(Coord, Dis)</p><p>WaitConvDis(坐标系, 等待增量)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Coord</td><td>SYNCOORD 变量</td><td>当前工件位置信息所参考的动坐标系，需与传送带配置界面中启用的动坐标系一致</td><td>必填</td></tr><tr><td>Dis</td><td>real</td><td>机器人待同步运动的增量值。直线传送带时，单位为 mm；圆盘传送带时，单位为 deg</td><td>必填</td></tr></tbody></table>',8)])])}const m=a(o,[["render",r]]);export{p as __pageData,m as default};
